SINA_SMART["anat3-face-osteology"] = {"lecture":"anat3-face-osteology","title":"Osteology of the face","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-face-osteology:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-face-osteology:s1","text":"Describe and explain: What the lecture covers","topic":"What the lecture covers","sec":1,"importance":"standard","highYield":"untested"},{"id":"anat3-face-osteology:e2","text":"Atlanto-occipital joint = nodding. Atlanto-axial joint = rotation.","topic":"How the skull sits on the neck","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e12","text":"Skull base bones: frontal, ethmoid, sphenoid, temporal, occipital.","topic":"Cranium (neurocranium): 8 bones","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e0","text":"22 skull bones = 8 cranial + 14 facial. The mandible and vomer are the two unpaired facial bones.","topic":"Facial skeleton (viscerocranium): 14 bones","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e3","text":"Sphenoid: sella turcica on the body; foramen rotundum (V2), ovale (V3) and spinosum (middle meningeal vessels) in the greater wing; optic canal in the lesser wing.","topic":"Sphenoid","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e4","text":"Ethmoid: cribriform plate (olfactory nerves), crista galli (falx cerebri), perpendicular plate (nasal septum), labyrinths (air cells, lamina papyracea, superior and middle conchae).","topic":"Ethmoid","sec":6,"importance":"core","highYield":"foundational"},{"id":"anat3-face-osteology:e10","text":"Pterion: frontal + parietal + squamous temporal + greater wing of sphenoid; thinnest part of the skull, over the anterior branch of the middle meningeal artery.","topic":"Temporal bone","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e5","text":"Temporal: squamous, petrous, tympanic, mastoid, styloid. Mandibular fossa for the TMJ. Zygomatic process forms the arch.","topic":"Temporal bone","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e6","text":"Zygomatic bone: three processes (frontal, temporal, maxillary); articulates with frontal, sphenoid, temporal and maxilla.","topic":"Zygomatic bone","sec":8,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e7","text":"Maxilla: body with the maxillary sinus plus four processes (frontal, zygomatic, alveolar, palatine). Infraorbital foramen below the orbit.","topic":"Maxilla","sec":9,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e8","text":"Nasal septum: perpendicular plate of the ethmoid + vomer.","topic":"Nasal bones, vomer, palatine, inferior nasal concha, lacrimal","sec":10,"importance":"core","highYield":"historically-high-yield"},{"id":"anat3-face-osteology:e9","text":"Mandible: mental foramen (mental nerve), mandibular foramen (inferior alveolar nerve), coronoid vs condylar processes, mandibular notch between them.","topic":"Mandible","sec":11,"importance":"core","highYield":"untested"},{"id":"anat3-face-osteology:e1","text":"Cranial bones: frontal, ethmoid, sphenoid, occipital, 2 parietal, 2 temporal.","topic":"Base of the skull","sec":12,"importance":"core","highYield":"foundational"},{"id":"anat3-face-osteology:e11","text":"Four paired paranasal sinuses: frontal, ethmoidal, sphenoid, maxillary (largest).","topic":"Paranasal sinuses","sec":13,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1ta32ra":"a","uy1nbu":"a","xymxbs":"a","3g3axz":"a","1au2ri9":"a","aqgbzl":"a","hpe1xw":"a","dfw8ia":"a","1vc6o14":"a","197735m":"a","j7t08m":"a","10yuht1":"a","mkfhqa":"a","7fcta3":"a","pch5lc":"a","fvq0vr":"a","o03yqu":"a","1aq1iuf":"a","xz4w4d":"a","vzr4jw":"a"},"mapCounts":{"verified":0,"auto":20,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-face-osteology:s0":{"s":0,"u":["Eight of them wrap the brain (the neurocranium) and fourteen shape the face, jaws, nose and eye sockets (the viscerocranium).","This lecture walks through them one by one, then looks at the underside of the skull and the air-filled sinuses."],"dp":[]},"anat3-face-osteology:s1":{"s":1,"u":["How the skull sits on the neck.","The cranium versus the facial bones."],"dp":[]},"anat3-face-osteology:e2":{"s":2,"u":["Atlanto-occipital joint = nodding. Atlanto-axial joint = rotation.","The atlanto-axial joint allows rotation, the \"no\" movement.","The atlanto-occipital joint allows nodding, the \"yes\" movement."],"dp":[{"h":"Note","t":"Atlanto-occipital = 'yes' (nodding); atlanto-axial = 'no' (rotation)."}]},"anat3-face-osteology:e12":{"s":3,"u":["Skull base bones: frontal, ethmoid, sphenoid, temporal, occipital.","Sphenoid: How many = 1; Note = Central bone of the skull base.","Occipital: How many = 1; Note = Back and base; the foramen magnum is here."],"dp":[{"h":"Why the sphenoid is called the keystone of the skull base","t":"The sphenoid sits in the centre of the skull base and touches almost every other skull bone (the exceptions are the nasal, lacrimal and mandible). It works as a cornerstone that spreads mechanical forces across the skull. It is also a crossroads for nerves and vessels going between the skull and the neck and face. Sources: Anatomy Standard, Os sphenoidale; Kenhub, The sphenoid bone."},{"h":"The three cranial fossae: a step-by-step view","t":"Looking down into the skull, the floor drops in three steps. The anterior fossa (frontal lobes) is formed by the frontal, ethmoid and sphenoid. The middle fossa (temporal lobes) is formed by the sphenoid and temporal bones, and holds most of the openings for the eye and jaw nerves. The posterior fossa (cerebellum) is formed by the temporal and occipital bones and holds the foramen magnum. Sources: Neurosurgical Atlas, Internal skull base anatomy; DocCheck Flexikon, Skull base."}]},"anat3-face-osteology:e0":{"s":4,"u":["22 skull bones = 8 cranial + 14 facial. The mandible and vomer are the two unpaired facial bones.","Unpaired (2): Mandible, vomer.","The mandible is the only bone of the skull that moves (at the temporomandibular joint)."],"dp":[{"h":"Note","t":"22 skull bones = 8 cranial + 14 facial . Unpaired facial bones: mandible and vomer . The mandible is the only mobile skull bone."}]},"anat3-face-osteology:e3":{"s":5,"u":["Sphenoid: sella turcica on the body; foramen rotundum (V2), ovale (V3) and spinosum (middle meningeal vessels) in the greater wing; optic canal in the lesser wing.","Openings: foramen rotundum (V2), foramen ovale (V3), foramen spinosum (middle meningeal vessels)..","The superior orbital fissure lies between the lesser and greater wings.."],"dp":[{"h":"Memory aid","t":"Sphenoid foramina for the trigeminal: 'Standing Room Only' : S uperior orbital fissure = V1, foramen R otundum = V2, foramen O vale = V3. Foramen spinosum = middle meningeal artery."},{"h":"Note","t":"Cranial fossae : anterior (cribriform); middle (optic canal, SOF, rotundum, ovale, spinosum, lacerum, carotid canal); posterior (internal acoustic meatus, jugular foramen, hypoglossal canal, foramen magnum)."}]},"anat3-face-osteology:e4":{"s":6,"u":["Ethmoid: cribriform plate (olfactory nerves), crista galli (falx cerebri), perpendicular plate (nasal septum), labyrinths (air cells, lamina papyracea, superior and middle conchae).","Crista galli: Upward projection of the midline plate; anchors the falx cerebri..","Perpendicular plate: Hangs down from the cribriform plate; forms the upper part of the bony nasal septum.."],"dp":[{"h":"Note","t":"Ethmoid : cribriform plate (CN I), crista galli (falx cerebri), perpendicular plate (upper septum ), labyrinths with superior and middle conchae and the lamina papyracea."}]},"anat3-face-osteology:e10":{"s":7,"u":["Pterion: frontal + parietal + squamous temporal + greater wing of sphenoid; thinnest part of the skull, over the anterior branch of the middle meningeal artery.","It is the thinnest part of the skull wall and lies over the anterior branch of the middle meningeal artery, so a blow there can tear the artery.","The pterion is the H-shaped meeting point on the side of the skull of four bones: frontal, parietal, squamous temporal and greater wing of the sphenoid."],"dp":[{"h":"Clinical","t":"Pterion (frontal + parietal + temporal + greater wing of sphenoid) is the thinnest spot, over the anterior branch of the middle meningeal artery → blow to the temple → extradural haematoma (lucid interval)."}]},"anat3-face-osteology:e5":{"s":7,"u":["Temporal: squamous, petrous, tympanic, mastoid, styloid. Mandibular fossa for the TMJ. Zygomatic process forms the arch.","Its zygomatic process meets the zygomatic bone to form the zygomatic arch.","The mastoid process is an attachment for sternocleidomastoid.."],"dp":[]},"anat3-face-osteology:e6":{"s":8,"u":["Zygomatic bone: three processes (frontal, temporal, maxillary); articulates with frontal, sphenoid, temporal and maxilla.","It articulates with four bones: frontal, sphenoid (greater wing), temporal and maxilla.","Temporal: Runs back to meet the temporal bone and form the zygomatic arch."],"dp":[]},"anat3-face-osteology:e7":{"s":9,"u":["Maxilla: body with the maxillary sinus plus four processes (frontal, zygomatic, alveolar, palatine). Infraorbital foramen below the orbit.","Infraorbital foramen: Below the orbit; the infraorbital nerve and vessels emerge here after the infraorbital groove and canal..","Body: Pyramid-shaped; contains the maxillary sinus, the largest paranasal sinus.."],"dp":[{"h":"Clinical","t":"The maxillary sinus ostium is high on its medial wall, so it drains poorly (sinusitis); its floor lies near the upper molar roots (toothache ↔ sinus pain)."}]},"anat3-face-osteology:e8":{"s":10,"u":["Nasal septum: perpendicular plate of the ethmoid + vomer.","Palatine (2): L-shaped: horizontal plate (posterior hard palate and nasal floor) and perpendicular plate (lateral nasal wall).","Forms the lower and posterior part of the bony nasal septum; meets the palatine, maxilla and ethmoid.."],"dp":[{"h":"Note","t":"The inferior nasal concha is a separate bone ; superior and middle conchae belong to the ethmoid . Bony septum = perpendicular plate of ethmoid + vomer ."}]},"anat3-face-osteology:e9":{"s":11,"u":["Mandible: mental foramen (mental nerve), mandibular foramen (inferior alveolar nerve), coronoid vs condylar processes, mandibular notch between them.","The inferior alveolar nerve and vessels enter here and run in the mandibular canal..","Transmits the mental nerve and vessels.."],"dp":[{"h":"The mandibular canal","t":"The inferior alveolar nerve enters the mandibular foramen and runs forward through the mandibular canal, supplying sensation to the lower teeth. Near the front it divides into its terminal branches: the mental nerve, which leaves through the mental foramen, and the incisive nerve. Sources: Radiopaedia, Mandible; MDWiki, Dentary."},{"h":"Note","t":"Mandible : mandibular foramen (inner ramus) = inferior alveolar nerve (dental block site); mental foramen (below premolars) = mental nerve. Coronoid process = temporalis; condylar process = TMJ."}]},"anat3-face-osteology:e1":{"s":12,"u":["Cranial bones: frontal, ethmoid, sphenoid, occipital, 2 parietal, 2 temporal.","The floor of the cranial cavity is made of five bones: frontal, ethmoid, sphenoid, temporal and occipital.","Anterior: Formed by = Orbital plates of the frontal, cribriform plate of the ethmoid, lesser wings of the sphenoid; Main openings = Cribriform foramina (olfactory nerves)."],"dp":[{"h":"Why the ethmoid is counted as both a cranial and a facial bone","t":"The ethmoid is a cranial bone, but only its cribriform plate contributes to the neurocranium. The rest of it (labyrinths and perpendicular plate) sits in the face, part of the nose and orbit. That is why some sources talk about 14 facial bones and others about 15 if the ethmoid is included. Source: Elsevier Anatomy, Ethmoid bone."}]},"anat3-face-osteology:e11":{"s":13,"u":["Four paired paranasal sinuses: frontal, ethmoidal, sphenoid, maxillary (largest).","Three sinuses lie in neurocranial bones (frontal, ethmoid, sphenoid).","Maxillary: Where = Body of the maxilla; the largest; Drains into = Middle meatus, at the hiatus semilunaris."],"dp":[{"h":"Sinus drainage: why sinus infections spread","t":"All the sinuses drain back into the nose. The middle meatus receives the frontal, anterior ethmoid and maxillary sinuses, all close together near the hiatus semilunaris. Because the frontal sinus drains just above the maxillary opening, fluid from the frontal sinus can run into the maxillary sinus. That is one route by which infection can spread between sinuses. Sources: TeachMeAnatomy, Paranasal sinuses; StatPearls, Anatomy, Head and Neck, Sinuses."},{"h":"Note","t":"Sinus drainage : frontal, maxillary and anterior ethmoid → middle meatus ; posterior ethmoid → superior meatus; sphenoid → sphenoethmoidal recess. The maxillary sinus is the largest ."}]}},"meta":{"1ta32ra":{"a":"recall","vg":"anat3-face-osteology:e0/recall/1"},"uy1nbu":{"a":"recall","vg":"anat3-face-osteology:e0/recall/2"},"xymxbs":{"a":"recall","vg":"anat3-face-osteology:e0/recall/3"},"3g3axz":{"a":"recall","vg":"anat3-face-osteology:e3/recall/1"},"1au2ri9":{"a":"recall","vg":"anat3-face-osteology:e3/recall/2"},"aqgbzl":{"a":"recall","vg":"anat3-face-osteology:e1/recall/1"},"hpe1xw":{"a":"recall","vg":"anat3-face-osteology:e8/recall/1"},"dfw8ia":{"a":"recall","vg":"anat3-face-osteology:e5/recall/1"},"1vc6o14":{"a":"recall","vg":"anat3-face-osteology:e12/recall/1"},"197735m":{"a":"recall","vg":"anat3-face-osteology:e7/recall/1"},"j7t08m":{"a":"recall","vg":"anat3-face-osteology:e9/recall/1"},"10yuht1":{"a":"recall","vg":"anat3-face-osteology:e9/recall/2"},"mkfhqa":{"a":"recall","vg":"anat3-face-osteology:e10/recall/1"},"7fcta3":{"a":"recall","vg":"anat3-face-osteology:s1/recall/1"},"pch5lc":{"a":"recall","vg":"anat3-face-osteology:e6/recall/1"},"fvq0vr":{"a":"recall","vg":"anat3-face-osteology:e8/recall/2"},"o03yqu":{"a":"recall","vg":"anat3-face-osteology:e12/recall/2"},"1aq1iuf":{"a":"recall","vg":"anat3-face-osteology:e6/recall/2"},"xz4w4d":{"a":"recall","vg":"anat3-face-osteology:e0/recall/4"},"vzr4jw":{"a":"recall","vg":"anat3-face-osteology:e6/recall/1"}},"explRev":"67571ac03da5"};
